import{_ as a,g as t,e as r,a4 as c}from"./chunks/framework.CEYJDsBW.js";const m=JSON.parse('{"title":"从正文或命令投影模板","description":"","frontmatter":{},"headers":[],"relativePath":"ageratum/26.1/packs/export.md","filePath":"ageratum/26.1/packs/export.md"}'),o={name:"ageratum/26.1/packs/export.md"};function n(s,e,i,d,u,l){return t(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="从正文或命令投影模板" tabindex="-1">从正文或命令投影模板 <a class="header-anchor" href="#从正文或命令投影模板" aria-label="Permalink to &quot;从正文或命令投影模板&quot;">​</a></h1><p>要用客户端命令投影同一份结构，将压缩二进制模板放在 <code>assets/workshop/ageratum/stands/basic.nbt</code>。按 F3+T 后，在世界中输入下列命令。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ageratum structure workshop:stands/basic ~ ~ ~</span></span></code></pre></div><p>命令索引只扫描 <code>ageratum/</code> 下的 <code>.nbt</code>，将文件夹前缀和扩展名去掉后作为模板 ID。它与正文 <code>structure</code> 标签的直接资源路径不同。模板管理器在客户端重载时接收原始 NBT，实际投影请求到来后再用当前世界的方块注册表装入 <code>StructureTemplate</code>。尚未进入世界时无法实例化模板。<a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/structure/AgeratumStructureTemplateManager.java" target="_blank" rel="noreferrer">模板注册与按需加载</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/command/AgeratumCommand.java" target="_blank" rel="noreferrer">投影命令</a></p><h2 id="从预览图拿到投影" tabindex="-1">从预览图拿到投影 <a class="header-anchor" href="#从预览图拿到投影" aria-label="Permalink to &quot;从预览图拿到投影&quot;">​</a></h2><p>打开有 <code>&lt;structure&gt;</code> 的页面，单击投影按钮。组件把当前模板交给 <code>StructureProjectionApi.showFloating</code>，在本地玩家面前显示浮动投影。该分支在这里没有发起服务器写盘操作，也没有手册专用的导出目录。要分发结构，直接把已有的 NBT 文件放入上述资源路径。<a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/component/extend/MDNBTStructureComponent.java" target="_blank" rel="noreferrer">页面按钮</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/structure/StructureProjectionApi.java" target="_blank" rel="noreferrer">投影 API</a></p>',6)])])}const b=a(o,[["render",n]]);export{m as __pageData,b as default};
